   $$bedrijfseconomie-vwo-2021-i-juicy-lucy-vraag5.png$$, $$2p 5 Welk punt uit informatiebron 1 hoort bij de O van de SWOT-analyse? Vermeld het bijbehorende nummer en onderbouw het antwoord met twee argumenten.$$, array['631c9a8b-6bbb-4079-828c-313ba1cb59e0', '78ad3ff7-1fb8-4c75-9a3c-33b44cb6054d', 'a34d60f5-ab98-4dd0-9ee5-66b433e634fe']::uuid[]),
